test('update-232: ONE CLICK SOLUTION\'s first page – the company\'s code opens that company\'s own sign-in; no list is given out', () => {
  const api = require(path.join(root, 'api', 'company.js'));
  const old = process.env.OCS_COMPANIES; delete process.env.OCS_COMPANIES;
  try {
    assert.deepStrictEqual(api.list(), { RCL: '/portal/' }, 'not set: only RCL, at this address\'s own Portal');
    assert.deepStrictEqual(api.find(' rcl '), { code: 'RCL', url: '/portal/' });
    for (const bad of ['', 'ABCD', 'R', '../x', 'RCL;DROP', '__proto__', 'constructor', 'toString']) assert.strictEqual(api.find(bad), null, bad);
    process.env.OCS_COMPANIES = 'RCL=/portal/, milestone=https://m.example.com/portal/; BAD=javascript:alert(1), X2=http://a.b/, Y2=//evil.example/';
    assert.deepStrictEqual(api.list(), { RCL: '/portal/', MILESTONE: 'https://m.example.com/portal/' }, 'only this address\'s own path or an https address');
    const ask = (method, url) => { const r = { h: {}, setHeader(k, v) { this.h[k] = v; }, end(b) { this.body = b; } }; api({ method, url }, r); return r; };
    let r = ask('GET', '/api/company?code=milestone'); assert.deepStrictEqual(JSON.parse(r.body), { ok: true, code: 'MILESTONE', url: 'https://m.example.com/portal/' }); assert.strictEqual(r.h['Cache-Control'], 'no-store');
    r = ask('GET', '/api/company?code=nobody'); assert.deepStrictEqual(JSON.parse(r.body), { ok: false }, 'a wrong code says nothing else');
    r = ask('GET', '/api/company'); assert.deepStrictEqual(JSON.parse(r.body), { ok: false }, 'no code: never the list');
    r = ask('POST', '/api/company?code=RCL'); assert.strictEqual(r.statusCode, 405);
  } finally { if (old === undefined) delete process.env.OCS_COMPANIES; else process.env.OCS_COMPANIES = old; }
  const page = fs.readFileSync(path.join(root, 'app', 'company.html'), 'utf8'), v = JSON.parse(fs.readFileSync(path.join(root, 'vercel.json'), 'utf8')), build = fs.readFileSync(path.join(root, 'build.js'), 'utf8');
  assert.ok(v.rewrites.some(x => x.source === '/company' && x.destination === '/company.html'));
  assert.match(build, /copyFileSync\(path\.join\(__dirname, 'app', 'company\.html'\), path\.join\(out, 'company\.html'\)\)/);
  assert.match(page, /<meta name="robots" content="noindex, nofollow">/);
  assert.match(page, /<img class="logo" src="\/icons\/oc-logo\.webp"[^>]*alt="One Click Solution">/);
  assert.ok(!/Rachana|RCL\b/.test(page.replace(/<!--[\s\S]*?-->/g, '').replace(/\/\*[\s\S]*?\*\//g, '')), 'One Click Solution\'s own page: no company is named on it');
  for (const f of ['tractor', 'fuel_pump', 'notebook', 'package', 'building_construction', 'bar_chart']) { assert.ok(page.includes('/icons/co-' + f + '.png'), f); assert.ok(fs.existsSync(path.join(root, 'app', 'icons', 'co-' + f + '.png')), f + ' file'); }
  assert.ok(fs.existsSync(path.join(root, 'app', 'icons', 'LICENSE-fluentui-emoji.txt')), 'the pictures\' licence travels with them');
  // every message in English, Marathi and Hindi
  const msg = new Function(page.slice(page.indexOf('var MSG = {'), page.indexOf('function say(k)')) + '; return MSG;')();
  for (const k of ['none', 'not', 'net']) { assert.strictEqual(msg[k].length, 3, k); assert.match(msg[k][1], /[ऀ-ॿ]/); assert.match(msg[k][2], /[ऀ-ॿ]/); }
  for (const m of page.matchAll(/<script(?![^>]*src)[^>]*>([\s\S]*?)<\/script>/g)) new Function(m[1]);
});

test('update-233: the HR module under the one address – /hr goes to its own project; its icon in the rail; nothing of HR is in this app', () => {
  const v = JSON.parse(fs.readFileSync(path.join(root, 'vercel.json'), 'utf8')), app = fs.readFileSync(path.join(root, 'app', 'App.html'), 'utf8');
  assert.deepStrictEqual(v.redirects.find(r => r.source === '/hr'), { source: '/hr', destination: '/hr/', permanent: false });
  assert.deepStrictEqual(v.rewrites.filter(r => /^\/hr\//.test(r.source)), [{ source: '/hr/', destination: 'https://rcl-hr.vercel.app/index.html' }, { source: '/hr/:path*', destination: 'https://rcl-hr.vercel.app/:path*' }]);
  // the other addresses keep their own rule: /ho/ (the Head Office site) and /hr/ are different, the order of the older rules is as before
  const src = v.rewrites.map(r => r.source);
  assert.ok(src.indexOf('/ho/') > -1 && src.indexOf('/hr/') > src.indexOf('/purchase/:path*'), 'added after the older rules');
  // never listed by a search engine (the rule of update-228 covers it)
  const h = v.headers.find(x => x.headers.some(k => k.key === 'X-Robots-Tag' && k.value === 'noindex, nofollow')), re = new RegExp('^' + h.source.replace(/^\//, '\\/') + '$');
  ['/hr/', '/hr/api/sso', '/hr/menu.json'].forEach(u => assert.ok(re.test(u), u));
  assert.match(app, /const NAV_IC = \{[^\n]*\n    hr: '<svg /);
  // the worker leaves /hr/ alone (update-99's rule)
  const sw = fs.readFileSync(path.join(root, 'app', 'sw.js'), 'utf8'), own = /if \(!(\/.+\/)\.test\(u\.pathname\)\) return;/.exec(sw);
  assert.ok(!eval(own[1]).test('/hr/'));
});

test('(update-237) Diesel Day Book: every entry of every place in one sheet – opening, inward, transfer (− / +), issue, closing; no place is chosen', () => {
  const { T, ctx } = require('./harness.js');
  const run = (fn, ...a) => { const r = require('vm').runInContext('(' + fn + ')', ctx)(...a); T.reset(); return r; };
  run('(x, m) => saveMaster_(x, m)', { no: 'DB-TIP', name: 'Tipper', type: 'Tipper', unit: 'KM', worksOn: ['KM'], kmStd: 4, owner: 'Rachana Construction Limited', ownership: 'Own', supply: 'Company', status: 'Active', activeFrom: '2026-01-01' }, 'add');
  const before = JSON.parse(JSON.stringify(run('f => rptDayBook_(f)', { from: '2026-02-09', to: '2026-02-09' })));
  const P = before.places, A = P[0], B = P[1];
  assert.ok(P.length >= 2, 'the test site has two diesel places');
  const a0 = before.closing[A], b0 = before.closing[B];
  run('x => saveInward_(x)', { date: '2026-02-10', location: A, pump: 'Pump', qty: 1000, rate: 90, billNo: 'DB1', billDate: '2026-02-10' });
  run('x => saveTransfer_(x)', { date: '2026-02-10', shift: 'Day', from: A, to: B, qty: 300 });
  run('x => saveDieselIssue_(x)', { date: '2026-02-10', shift: 'Day', source: B, no: 'DB-TIP', qty: 120, kmReading: 500, driver: 'Driver One', force: true });
  run('x => saveDieselIssue_(x)', { date: '2026-02-12', shift: 'Day', source: A, no: 'DB-TIP', qty: 80, kmReading: 900, force: true });
  const d = JSON.parse(JSON.stringify(run('f => rptDayBook_(f)', { from: '2026-02-10', to: '2026-02-12' })));
  assert.deepStrictEqual(d.days.map(x => x.date), ['2026-02-10', '2026-02-12'], 'only the days with an entry');
  const d1 = d.days[0], d2 = d.days[1];
  assert.deepStrictEqual([d1.open[A], d1.open[B]], [a0, b0]);
  assert.deepStrictEqual(d1.rows.map(r => r.kind), ['Inward', 'Transfer', 'Issue'], 'a transfer is ONE line');
  assert.deepStrictEqual(d1.rows[0].d, { [A]: 1000 });
  assert.strictEqual(d1.rows[0].who, 'Pump → ' + A); assert.match(d1.rows[0].detail, /Bill DB1 · Rate 90/);
  assert.deepStrictEqual(d1.rows[1].d, { [A]: -300, [B]: 300 }); assert.strictEqual(d1.rows[1].who, A + ' → ' + B);
  assert.deepStrictEqual(d1.rows[2].d, { [B]: -120 }); assert.match(d1.rows[2].who, /^DB-TIP – Tipper \(Own\)$/); assert.match(d1.rows[2].detail, /500 km · Driver One/);
  assert.deepStrictEqual([d1.close[A], d1.close[B]], [a0 + 700, b0 + 180]);
  assert.deepStrictEqual([d1.inward, d1.transfer, d1.issued], [1000, 300, 120]);
  assert.deepStrictEqual([d2.open[A], d2.open[B], d2.close[A], d2.close[B]], [a0 + 700, b0 + 180, a0 + 620, b0 + 180], 'the next day opens with the closing of the day before');
  assert.deepStrictEqual(d.total, { inward: 1000, transfer: 300, issued: 200, entries: 4 });
  assert.deepStrictEqual([d.closing[A], d.closing[B]], [a0 + 620, b0 + 180]);
  // the same closing as the Stock Register of each place (the report the stock is already read from)
  [A, B].forEach(p => assert.strictEqual(JSON.parse(JSON.stringify(run('f => rptStock_(f)', { from: '2026-02-10', to: '2026-02-12', location: p }))).total.closing, d.closing[p], p));
  // a period with no entry: no day, the stock as it stands
  const none = JSON.parse(JSON.stringify(run('f => rptDayBook_(f)', { from: '2026-02-11', to: '2026-02-11' })));
  assert.deepStrictEqual([none.days.length, none.closing[A], none.opening[A]], [0, a0 + 700, a0 + 700]);
  // the page: its report, its guide, no place filter, Today / Yesterday
  const app = require('fs').readFileSync(require('path').join(__dirname, '..', 'app', 'App.html'), 'utf8');
  assert.match(app, /\{ key: 'daybook', label: 'Diesel Day Book', fn: 'rptDayBook', portrait: false, filters: \['days'\],/);
  assert.match(app, /data-tday="' \+ k \+ '">Today<\/button><button class="btn ghost small" data-yday=/);  // (update-238) each diesel source has its own block of columns – Opening · Received · Transfer · Issued · Balance; no "All places"
  assert.match(app, /<th colspan="5" class="db-src bs">' \+ esc\(p\) \+ '<\/th>/);
  assert.match(app, /<th class="n bs">Opening<\/th><th class="n">Received<\/th><th class="n">Transfer<\/th><th class="n">Issued<\/th><th class="n be">Balance<\/th>/);
  const def = app.slice(app.indexOf("{ key: 'daybook'"), app.indexOf("{ key: 'compare'"));
  assert.ok(def.indexOf('All places') === -1, 'no "All places" column in the Day Book');
  // (update-239) the headings come under every date (not once at the top)
  assert.match(def, /getDay\(\)\], n\) \+ heads \+ lines \+ totalRow\('Total of '/);
  assert.ok(def.indexOf('<thead>') === -1);
});

