test('update-242: a sideways scroll bar at the bottom of the screen for a wide table – drawn by the page, changes nothing of a table', () => {
  const page = fs.readFileSync(path.join(__dirname, '..', 'app', 'App.html'), 'utf8'), i = page.indexOf("if (window.HSB) return; window.HSB = true;"); assert.ok(i > 0 && page.indexOf("if (window.HSB) return;", i + 10) < 0, 'the script is in the page once');
  const js = page.slice(page.lastIndexOf('<script>', i) + 8, page.indexOf('</script>', i)); new Function(js);      // it parses
  assert.match(js, /r\.top < h - 80 && r\.bottom > h \+ 2/, 'only while the table\'s own end is below the screen'); assert.match(js, /cur\.scrollLeft = Math\.round\(/, 'it only moves the table sideways');
  assert.ok(!/innerHTML|fetch\(|google\.script|\.remove\(\)|textContent = [^c]/.test(js.replace("css.textContent = ", '')), 'nothing of the page\'s content or data is read or changed'); assert.match(js, /@media print\{#hsb\{display:none!important\}\}/, 'never printed');
  assert.match(page, /^ {2}html, body \{ overscroll-behavior-x: none; \}$/m, 'two fingers sideways: no page back'); assert.match(fs.readFileSync(path.join(__dirname, '..', 'app', 'Index.html'), 'utf8'), /overscroll-behavior-x: none/, 'in the outer frame too');
});

test('update-243: HR\'s own backup Sheets (kept at the first site, like the Portal\'s and Purchase\'s) – its export, the Portal\'s ticket, the nightly job, the help', () => {
  const bx = require('../server/bkexport'), env = { HR_URL: process.env.HR_URL, BACKUP_EXPORT_SECRET: process.env.BACKUP_EXPORT_SECRET };
  try {
    delete process.env.HR_URL; process.env.BACKUP_EXPORT_SECRET = 'x'.repeat(30);
    assert.strictEqual(bx.base('hr'), 'https://rcl-hr.vercel.app'); assert.strictEqual(bx.on().hr, true); assert.strictEqual(bx.base('pur'), 'https://rcl-purchase.vercel.app');
    process.env.HR_URL = 'http://127.0.0.1:3060/'; assert.strictEqual(bx.base('hr'), 'http://127.0.0.1:3060');
  } finally { Object.keys(env).forEach(k => { if (env[k] === undefined) delete process.env[k]; else process.env[k] = env[k]; }); }
  const bk = require('../server/backup.vm.js'), a = bk.indexOf('function bkTarget_('), b = bk.indexOf('const bkUrl_ = ');
  const X = new Function(bk.slice(a, b) + '; return { bkTarget_, BK_OWN_ };')();
  assert.deepStrictEqual(X.bkTarget_({ target: 'hr' }), { kind: 'hr', lock: 'backup_hr', state: 'BK_HR_STATE', info: 'SB_HR_INFO', sheets: 'BK_HR_SHEETS', name: 'HR' });
  assert.strictEqual(X.bkTarget_({ target: 'purchase' }).sheets, 'BK_PUR_SHEETS'); assert.strictEqual(X.bkTarget_({ target: 'portal' }).sheets, 'BK_PORTAL_SHEETS'); assert.strictEqual(X.bkTarget_({ target: 'hrme' }).kind, 'site');
  assert.deepStrictEqual([X.BK_OWN_.hr.src, X.BK_OWN_.hr.prefix, X.BK_OWN_.hr.where], ['hr', 'HR – ', 'Portal → Sites → HR backup']);
  assert.match(bk, /hr: \[\.\.\.new Set\(hr\.filter\(Boolean\)\)\]/, 'its Sheets are never given to a site, the Portal or Purchase');
  assert.match(bk, /if \(T\.kind === 'hr' && !Object\.keys\(rem\)\.length\) throw new Error\('The HR backup needs the same BACKUP_EXPORT_SECRET/);
  assert.match(bk, /c\.target === 'portal' \|\| c\.target === 'purchase' \|\| c\.target === 'hr'\) \? c\.target : '', budget/, 'Backup now');
  const sy = fs.readFileSync(path.join(root, 'server', 'system.js'), 'utf8');
  assert.match(sy, /const own = c\.target === 'portal' \|\| c\.target === 'purchase' \|\| c\.target === 'hr' \? c\.target : '';/); assert.match(sy, /if \(own !== 'hr'\) \(ids\.hr \|\| \[\]\)\.forEach/);
  assert.match(fs.readFileSync(path.join(root, 'api', 'backup.js'), 'utf8'), /\{ site: '', opt: Object\.assign\(\{\}, opt, \{ target: 'purchase' \}\) \}, \{ site: '', opt: Object\.assign\(\{\}, opt, \{ target: 'hr' \}\) \}\]\);/);
  const app = fs.readFileSync(path.join(root, 'app', 'App.html'), 'utf8');
  const H = new Function(app.slice(app.indexOf('const FIX_RULES = ['), app.indexOf('function fixInner(')) + '; return { fixRules, FIX_ANY };')();
  const full = H.fixRules('Sheet 2 of HR is full – Google allows 10 million cells in one Sheet.')[0], ex = H.fixRules('HR refused the backup (BACKUP_EXPORT_SECRET must be the same value).')[0];
  assert.ok(full !== H.FIX_ANY && /10 million cells/.test(full.en.join(' ')) && full.mr && full.hi);
  assert.ok(ex !== H.FIX_ANY && /rcl-hr/.test(ex.en.join(' ')) && /rcl-hr/.test(ex.mr.join(' ')) && /rcl-hr/.test(ex.hi.join(' ')));
});

test('update-244: the web has its own language (webLang) – English until the person chooses; a picker on top; the phone app\'s language no longer turns the web, nor the web\'s the app', () => {
  const app = fs.readFileSync(path.join(root, 'app', 'App.html'), 'utf8'), code = fs.readFileSync(path.join(root, 'app', 'Code.gs'), 'utf8');
  assert.match(app, /<select class="web-lang" id="web_lang" data-noi18n hidden [^>]*><option value="en">English<\/option><option value="mr">मराठी<\/option><option value="hi">हिंदी<\/option><\/select>/);
  assert.match(app, /\$\('web_lang'\)\.addEventListener\('change', e => \{ const v = e\.target\.value; if \(S\.user && \(v === 'en' \|\| v === 'mr' \|\| v === 'hi'\)\) prefSet\(\{ webLang: v \}\); \}\);/);
  assert.match(app, /wlp\.hidden = !S\.user; wlp\.value = p\.webLang === 'mr' \|\| p\.webLang === 'hi' \? p\.webLang : 'en';/);
  assert.ok(!/i18nSet\(S\.prefs\.appLang\)/.test(app) && !/fixLang = S\.prefs\.lang/.test(app), 'the phone app\'s choice does not turn the web');
  assert.ok(!/prefSet\([^)]*appLang/.test(app), 'the web never writes the phone app\'s language');
  assert.match(app, /let fixLang = 'en';/); assert.match(app, /webLang: '', lbMode/);
  const { T, ctx } = require('./harness.js'), run = (fn, ...a) => { const r = require('vm').runInContext('(' + fn + ')', ctx)(...a); T.reset(); return JSON.parse(JSON.stringify(r === undefined ? null : r)); };
  assert.deepStrictEqual(['mr', 'hi', '', 'en', 'xx', undefined].map(v => run('v => prefsClean_({ webLang: v }).webLang', v)), ['mr', 'hi', '', 'en', '', '']);
  assert.deepStrictEqual(run('() => { const p = prefsClean_({ appLang: "mr", lang: "mr" }); return [p.appLang, p.lang, p.webLang]; }'), ['mr', 'mr', ''], 'Marathi in the phone app: the web stays English');
  assert.match(code, /o\.appLang !== was\.appLang \|\| o\.lang !== was\.lang \|\| o\.webLang !== was\.webLang\) langSpread_/);
  assert.match(code, /JSON\.stringify\(\[str_\(email\)\.toLowerCase\(\), o\.appLang, o\.lang, o\.webLang\]\)/);
  assert.match(code, /if \(webLang !== undefined && webLang !== null\) p\.webLang = webLang;/);
});

test('update-246: the lists of Diesel Issue, Inward and Transfer show WHEN each entry was saved – a "Time" column beside the date', () => {
  const app = fs.readFileSync(path.join(root, 'app', 'App.html'), 'utf8'), code = fs.readFileSync(path.join(root, 'app', 'Code.gs'), 'utf8');
  // the server: the moment of the first save, on the site's clock – in each of the three lists
  assert.strictEqual((code.match(/at: H\.CREATED in c \? savedAt_\(sentAt\(r\[c\[H\.CREATED\]\], [^)]*\)\) : '',/g) || []).length, 3);      // (update-247: the moment it was sent)
  const { T, ctx } = require('./harness.js'), run = (fn, ...a) => { const r = require('vm').runInContext('(' + fn + ')', ctx)(...a); T.reset(); return JSON.parse(JSON.stringify(r === undefined ? null : r)); };
  assert.deepStrictEqual(run('() => [savedAt_(new Date("2026-11-14T04:12:00Z")), savedAt_(new Date("2026-11-14T20:05:00Z")), savedAt_(""), savedAt_("x"), savedAt_(new Date("no"))]'), ['2026-11-14 09:42', '2026-11-15 01:35', '', '', ''], 'India time; nothing for an entry without it');
  // the page: a heading and a cell in each list; the empty line and the totals as wide as the heading
  assert.strictEqual((app.match(/<th>Date<\/th><th class="at" title="When the entry was saved">Time<\/th>/g) || []).length, 3);
  assert.strictEqual((app.match(/esc\(showDate\(r\.date\)\) \+ '<\/td>' \+ atCell\(r\) \+ '<td>'/g) || []).length, 3);
  const body = app.slice(app.indexOf('  function atCell(r) {'), app.indexOf('  function byCell(r) {'));
  const atCell = new Function('showDate', body + '; return atCell;')(dk => { const p = String(dk).split('-'); return p[2] + '-' + p[1] + '-' + p[0]; });
  assert.strictEqual(atCell({ date: '2026-11-14', at: '2026-11-14 09:42' }), '<td class="at"><b>09:42 AM</b></td>');
  assert.strictEqual(atCell({ date: '2026-11-14', at: '2026-11-14 13:05' }), '<td class="at"><b>01:05 PM</b></td>');
  assert.strictEqual(atCell({ date: '2026-11-14', at: '2026-11-14 00:07' }), '<td class="at"><b>12:07 AM</b></td>');
  assert.strictEqual(atCell({ date: '2026-11-14', at: '2026-11-14 12:00' }), '<td class="at"><b>12:00 PM</b></td>');
  assert.strictEqual(atCell({ date: '2026-11-12', at: '2026-11-14 18:30' }), '<td class="at"><b>06:30 PM</b><small>14-11-2026</small></td>', 'saved on another day: that day is shown too');
  ['', undefined, 'x', '<img src=x>'].forEach(v => assert.strictEqual(atCell({ date: '2026-11-14', at: v }), '<td class="at"><span class="muted">–</span></td>'));
  assert.match(app, /colspan="16" class="none">No diesel issues/); assert.match(app, /colspan="13" class="none">No inward entries/); assert.match(app, /colspan="11" class="none">No transfers/);
});

test('update-247: the time in the lists is the moment the USER SENT the entry – not the later moment it was approved and written', () => {
  const code = fs.readFileSync(path.join(root, 'app', 'Code.gs'), 'utf8');
  assert.strictEqual((code.match(/const sentAt = sentAtOf_\('Diesel (Issue|Inward|Transfer)'\);/g) || []).length, 3);
  assert.strictEqual((code.match(/savedAt_\(sentAt\(r\[c\[H\.CREATED\]\], /g) || []).length, 3);
  assert.ok(!/H\.CREATED, (new Date|req)/.test(code.slice(code.indexOf('function sentAtPick_'), code.indexOf('function tStr_'))), 'nothing is written: "Created At" stays – the order of the stock follows it');
  const { T, ctx } = require('./harness.js'), run = (fn, ...a) => { const r = require('vm').runInContext('(' + fn + ')', ctx)(...a); T.reset(); return JSON.parse(JSON.stringify(r === undefined ? null : r)); };
  const pick = (reqs, made, no) => run(`(reqs, made, no) => { const l = reqs.map(x => ({ req: new Date(x[0]), dec: new Date(x[1]).getTime(), nos: x[2] })), r = sentAtPick_(l, new Date(made).getTime(), no); return r ? savedAt_(r) : ''; }`, reqs, made, no);
  // his case: sent 14:31, approved (= written) 17:02 – three entries approved one after the other
  const reqs = [['2026-11-14T09:01:10Z', '2026-11-14T11:32:05Z', 'MH25AJ5741'], ['2026-11-14T09:05:40Z', '2026-11-14T11:32:20Z', 'MH25AJ2169'], ['2026-11-14T09:20:00Z', '2026-11-14T11:32:41Z', 'MH04LE7533,MH12AB1234']];
  assert.strictEqual(pick(reqs, '2026-11-14T11:32:03Z', 'MH-25-AJ-5741'), '2026-11-14 14:31');
  assert.strictEqual(pick(reqs, '2026-11-14T11:32:18Z', 'MH-25-AJ-2169'), '2026-11-14 14:35', 'the request of ITS machinery, though another was approved 15 s before');
  assert.strictEqual(pick(reqs, '2026-11-14T11:32:40Z', 'mh-12-ab-1234'), '2026-11-14 14:50', 'several entries in one request');
  assert.strictEqual(pick(reqs, '2026-11-14T11:32:18Z', ''), '2026-11-14 14:35', 'no machinery (inward, transfer): the nearest save');
  assert.strictEqual(pick(reqs, '2026-11-14T06:00:00Z', 'MH-25-AJ-5741'), '', 'saved without verification: no request of that moment');
  assert.strictEqual(pick(reqs, '2026-11-14T11:35:00Z', 'MH-25-AJ-5741'), '', 'a later entry of the same machinery is not this request\'s');
  assert.strictEqual(pick([], '2026-11-14T11:32:03Z', 'X'), '');
  // without the requests' table the lists work as before (the entry's own time)
  assert.deepStrictEqual(run('() => { const f = sentAtOf_("Diesel Issue"), d = new Date("2026-11-14T04:12:00Z"); return [savedAt_(f(d, "X")), f("", "X")]; }'), ['2026-11-14 09:42', '']);
});
